// mcserver - dedicated co-op server for the voxel game.
//
// It is the authoritative copy of everything that used to live in the host's
// browser: players, block edit log, chat, PvP, world time, persistence.
// Terrain itself is still generated by each client from the shared seed; the
// server only stores the sparse list of edits on top of that terrain.
//
// It also serves the game page (index.html, embedded) so players just open
// http://<server>:8080 and press "Join Online Game".
package main

import (
	"crypto/subtle"
	"encoding/base64"
	"encoding/binary"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"log"
	"math"
	"math/rand"
	"net"
	"net/http"
	"os"
	"os/exec"
	"os/signal"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"syscall"
	"time"

	_ "embed"

	"github.com/gorilla/websocket"
)

//go:embed index.html
var indexHTML []byte

const (
	netVersion = 3 // must match NET_VERSION in index.html
	worldW     = 5000
	worldD     = 5000
	maxY       = 100
	maxPlayers = 8
	editChunk  = 48000
	maxHealth  = 20
	pvpReach   = 4.2
	pvpDamage  = 4
	dayLength  = 20 * 60.0 // seconds per in-game day
	startTime  = 0.30
)

type M map[string]any

// ---------------------------------------------------------------- types

type player struct {
	id         int
	name       string
	conn       *websocket.Conn
	send       chan []byte
	done       chan struct{}
	joined     bool
	x, y, z    float64
	yaw, pitch float64
	health     int
	dead       bool
	lastAttack time.Time
}

// inMsg is every message a client can send; unused fields stay zero.
type inMsg struct {
	T     string  `json:"t"`
	V     int     `json:"v"`
	Name  string  `json:"name"`
	X     float64 `json:"x"`
	Y     float64 `json:"y"`
	Z     float64 `json:"z"`
	Yaw   float64 `json:"yaw"`
	Pitch float64 `json:"pitch"`
	ID    float64 `json:"id"`
	M     string  `json:"m"`
	Dmg   float64 `json:"dmg"` // custom weapon stats (optional)
	Reach float64 `json:"reach"`
	Cd    float64 `json:"cd"`
}

type saveFile struct {
	Seed  int32       `json:"seed"`
	Mode  string      `json:"mode"`
	Time  float64     `json:"time"`
	PVP   bool        `json:"pvp"`
	Spawn *[3]float64 `json:"spawn,omitempty"`
	Edits []byte      `json:"edits"` // 5 bytes per edit: uint32 LE voxel index + block id
}

type server struct {
	mu             sync.Mutex
	opMu           sync.Mutex
	seed           int32
	mode           string
	pvp            bool
	wtime          float64
	spawn          *[3]float64
	edits          map[uint32]uint8
	players        map[int]*player
	nextID         int
	simID          int // player whose client runs the fluid simulation
	dirty          bool
	savePath       string
	definitionsDir string
	operatorCode   string
	opAttempts     map[string]operatorAttempt
}

type operatorAttempt struct {
	failures int
	expires  time.Time
}

var upgrader = websocket.Upgrader{
	ReadBufferSize:  4096,
	WriteBufferSize: 4096,
	CheckOrigin:     func(r *http.Request) bool { return true },
}

// ---------------------------------------------------------------- helpers

func isInt(f float64) bool { return f == math.Trunc(f) && math.Abs(f) < 1e9 }

func voxelIndex(x, y, z int) uint32 {
	return (uint32(z)*worldW+uint32(x))*maxY + uint32(y)
}

func cleanName(s string) string {
	var b strings.Builder
	for _, r := range s {
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') ||
			r == '_' || r == '-' || r == ' ' {
			b.WriteRune(r)
		}
	}
	out := strings.TrimSpace(b.String())
	if len(out) > 16 {
		out = strings.TrimSpace(out[:16])
	}
	return out
}

func rayAABB(ox, oy, oz, dx, dy, dz float64, lo, hi [3]float64, maxT float64) float64 {
	o := [3]float64{ox, oy, oz}
	d := [3]float64{dx, dy, dz}
	tmin, tmax := 0.0, maxT
	for i := 0; i < 3; i++ {
		if math.Abs(d[i]) < 1e-9 {
			if o[i] < lo[i] || o[i] > hi[i] {
				return -1
			}
			continue
		}
		t1 := (lo[i] - o[i]) / d[i]
		t2 := (hi[i] - o[i]) / d[i]
		if t1 > t2 {
			t1, t2 = t2, t1
		}
		if t1 > tmin {
			tmin = t1
		}
		if t2 < tmax {
			tmax = t2
		}
		if tmin > tmax {
			return -1
		}
	}
	return tmin
}

// ---------------------------------------------------------------- sending (caller holds s.mu)

func (s *server) sendRaw(p *player, b []byte) {
	select {
	case p.send <- b:
	default:
		go p.conn.Close() // client can't keep up: drop it
	}
}

func (s *server) sendTo(p *player, v any) {
	b, err := json.Marshal(v)
	if err != nil {
		return
	}
	s.sendRaw(p, b)
}

func (s *server) broadcast(v any, except *player) {
	b, err := json.Marshal(v)
	if err != nil {
		return
	}
	for _, q := range s.players {
		if q != except {
			s.sendRaw(q, b)
		}
	}
}

func (s *server) sys(p *player, text string) {
	s.sendTo(p, M{"t": "c", "n": "Server", "m": text})
}

func (s *server) reject(p *player, msg string) {
	s.sendTo(p, M{"t": "err", "m": msg})
	go func() {
		time.Sleep(400 * time.Millisecond)
		p.conn.Close()
	}()
}

// ---------------------------------------------------------------- join / leave

func (s *server) uniqueName(n string, id int) string {
	if n == "" {
		n = "Player" + strconv.Itoa(id)
	}
	used := map[string]bool{}
	for _, q := range s.players {
		used[q.name] = true
	}
	out := n
	for i := 2; used[out]; i++ {
		base := n
		if len(base) > 13 {
			base = base[:13]
		}
		out = base + strconv.Itoa(i)
	}
	return out
}

func (s *server) encodeEdits() []byte {
	buf := make([]byte, 0, len(s.edits)*5)
	var tmp [4]byte
	for idx, v := range s.edits {
		binary.LittleEndian.PutUint32(tmp[:], idx)
		buf = append(buf, tmp[:]...)
		buf = append(buf, v)
	}
	return buf
}

func (s *server) join(p *player, m *inMsg) {
	if p.joined {
		return
	}
	if m.V != netVersion {
		s.reject(p, "Version mismatch - reload the page")
		return
	}
	if len(s.players) >= maxPlayers {
		s.reject(p, "Room is full")
		return
	}
	s.nextID++
	p.id = s.nextID
	p.name = s.uniqueName(cleanName(m.Name), p.id)
	p.health = maxHealth
	if s.spawn != nil {
		p.x, p.y, p.z = s.spawn[0], s.spawn[1], s.spawn[2]
	}
	if s.simID == 0 {
		s.simID = p.id
	}

	plist := []M{}
	for _, q := range s.players {
		plist = append(plist, M{"id": q.id, "name": q.name, "x": q.x, "y": q.y, "z": q.z,
			"yaw": q.yaw, "pitch": q.pitch, "dead": q.dead})
	}
	eb := s.encodeEdits()
	nChunks := (len(eb) + editChunk - 1) / editChunk
	welcome := M{
		"t": "welcome", "id": p.id, "seed": s.seed, "mode": s.mode, "time": s.wtime,
		"pvp": s.pvp, "players": plist, "editBytes": len(eb), "chunks": nChunks,
		"sim": s.simID == p.id, "spawn": nil,
	}
	if s.spawn != nil {
		welcome["spawn"] = M{"x": s.spawn[0], "y": s.spawn[1], "z": s.spawn[2]}
	}
	s.sendTo(p, welcome)
	for i := 0; i < nChunks; i++ {
		end := (i + 1) * editChunk
		if end > len(eb) {
			end = len(eb)
		}
		s.sendTo(p, M{"t": "edits", "i": i, "d": base64.StdEncoding.EncodeToString(eb[i*editChunk : end])})
	}

	p.joined = true
	s.players[p.id] = p
	s.broadcast(M{"t": "j", "id": p.id, "name": p.name}, p)
	log.Printf("+ %s joined (id %d, %d players)", p.name, p.id, len(s.players))
}

func (s *server) drop(p *player) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if !p.joined {
		return
	}
	p.joined = false
	delete(s.players, p.id)
	s.broadcast(M{"t": "l", "id": p.id, "name": p.name}, nil)
	log.Printf("- %s left (%d players)", p.name, len(s.players))
	if s.simID == p.id {
		s.simID = 0
		for id := range s.players {
			if s.simID == 0 || id < s.simID {
				s.simID = id
			}
		}
		if q := s.players[s.simID]; q != nil {
			s.sendTo(q, M{"t": "sim", "on": true})
		}
	}
	s.dirty = true
	if len(s.players) == 0 {
		go s.save(true)
	}
}

// ---------------------------------------------------------------- message handling

func (s *server) handle(p *player, m *inMsg) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if m.T == "hello" {
		s.join(p, m)
		return
	}
	if !p.joined {
		return
	}
	switch m.T {
	case "p":
		s.onPos(p, m)
	case "b":
		s.onBlock(p, m)
	case "c":
		s.onChat(p, m)
	case "spawn":
		if s.spawn == nil && math.Abs(m.X) < 1e6 && math.Abs(m.Y) < 1e6 && math.Abs(m.Z) < 1e6 {
			s.spawn = &[3]float64{m.X, m.Y, m.Z}
			s.dirty = true
		}
	case "pvp-attack":
		if isInt(m.ID) {
			s.pvpAttack(p, int(m.ID), m)
		}
	case "pvp-dead":
		if s.pvp {
			p.dead, p.health = true, 0
			s.broadcast(M{"t": "pvp-health", "id": p.id, "health": 0, "dead": true, "amount": 0}, nil)
		}
	case "pvp-respawn":
		s.pvpRespawn(p)
	}
}

func (s *server) onPos(p *player, m *inMsg) {
	if math.Abs(m.X) > 1e6 || math.Abs(m.Y) > 1e6 || math.Abs(m.Z) > 1e6 {
		return
	}
	if p.dead {
		if s.pvp {
			return
		}
		p.dead, p.health = false, maxHealth
		s.broadcast(M{"t": "pvp-respawn", "id": p.id, "x": m.X, "y": m.Y, "z": m.Z}, p)
	}
	p.x, p.y, p.z, p.yaw, p.pitch = m.X, m.Y, m.Z, m.Yaw, m.Pitch
	s.broadcast(M{"t": "p", "id": p.id, "x": m.X, "y": m.Y, "z": m.Z, "yaw": m.Yaw, "pitch": m.Pitch}, p)
}

func (s *server) onBlock(p *player, m *inMsg) {
	if !isInt(m.X) || !isInt(m.Y) || !isInt(m.Z) || !isInt(m.ID) {
		return
	}
	x, y, z, id := int(m.X), int(m.Y), int(m.Z), int(m.ID)
	if x < 0 || x >= worldW || z < 0 || z >= worldD || y < 1 || y >= maxY { // y=0 is bedrock
		return
	}
	// 9 = bedrock, 100-118 = built-in items; chunk data is one byte, so blocks are 0-255
	if id < 0 || id > 255 || id == 9 || (id >= 100 && id <= 118) {
		return
	}
	idx := voxelIndex(x, y, z)
	if old, ok := s.edits[idx]; ok && int(old) == id {
		return
	}
	s.edits[idx] = uint8(id)
	s.dirty = true
	s.broadcast(M{"t": "b", "x": x, "y": y, "z": z, "id": id}, p)
}

func (s *server) isOp(p *player) bool {
	for id := range s.players {
		if id < p.id {
			return false
		}
	}
	return true
}

func (s *server) onChat(p *player, m *inMsg) {
	r := []rune(strings.TrimSpace(m.M))
	if len(r) > 120 {
		r = r[:120]
	}
	text := strings.TrimSpace(string(r))
	if text == "" {
		return
	}
	if strings.HasPrefix(text, "/") {
		s.command(p, text)
		return
	}
	log.Printf("<%s> %s", p.name, text)
	s.broadcast(M{"t": "c", "n": p.name, "m": text}, nil)
}

func (s *server) command(p *player, text string) {
	f := strings.Fields(strings.ToLower(text))
	switch f[0] {
	case "/pvp":
		if !s.isOp(p) {
			s.sys(p, "Only the first player in the room can toggle PvP")
			return
		}
		on := !s.pvp
		if len(f) > 1 {
			on = f[1] == "on"
		}
		s.pvp = on
		s.dirty = true
		for _, q := range s.players {
			q.dead, q.health = false, maxHealth
		}
		s.broadcast(M{"t": "pvp-mode", "enabled": s.pvp}, nil)
	case "/list":
		names := []string{}
		for _, q := range s.players {
			names = append(names, q.name)
		}
		s.sys(p, fmt.Sprintf("Players (%d/%d): %s", len(names), maxPlayers, strings.Join(names, ", ")))
	default:
		s.sys(p, "Commands: /pvp [on|off], /list")
	}
}

// ---------------------------------------------------------------- PvP

func clampF(v, lo, hi, def float64) float64 {
	if v == 0 || math.IsNaN(v) {
		return def
	}
	return math.Max(lo, math.Min(hi, v))
}

func (s *server) pvpAttack(a *player, targetID int, m *inMsg) {
	if !s.pvp || a.dead || targetID == a.id {
		return
	}
	t := s.players[targetID]
	now := time.Now()
	if t == nil || t.dead || now.Sub(a.lastAttack) < time.Duration(clampF(m.Cd, 0.1, 5, 0.5)*float64(time.Second)) {
		return
	}
	cp := math.Cos(a.pitch)
	dx, dy, dz := -math.Sin(a.yaw)*cp, math.Sin(a.pitch), -math.Cos(a.yaw)*cp
	hit := rayAABB(a.x, a.y+1.5, a.z, dx, dy, dz,
		[3]float64{t.x - 0.3, t.y, t.z - 0.3}, [3]float64{t.x + 0.3, t.y + 1.8, t.z + 0.3}, clampF(m.Reach, 0.5, 8, pvpReach))
	if hit < 0 {
		return
	}
	a.lastAttack = now
	kx, kz := t.x-a.x, t.z-a.z
	l := math.Hypot(kx, kz)
	if l == 0 {
		l = 1
	}
	kx, kz = kx/l, kz/l
	damage := int(math.Round(clampF(m.Dmg, 1, maxHealth, pvpDamage)))
	t.health -= damage
	if t.health < 0 {
		t.health = 0
	}
	t.dead = t.health <= 0
	upd := func(amount int) M {
		return M{"t": "pvp-health", "id": t.id, "amount": amount, "by": a.name,
			"health": t.health, "dead": t.dead, "knockX": kx, "knockZ": kz}
	}
	s.sendTo(t, upd(damage))
	s.broadcast(upd(0), t)
}

func (s *server) pvpRespawn(p *player) {
	if !s.pvp || !p.dead {
		return
	}
	p.dead, p.health = false, maxHealth
	x, y, z := p.x, p.y, p.z
	if s.spawn != nil {
		x, y, z = s.spawn[0], s.spawn[1], s.spawn[2]
	}
	p.x, p.y, p.z = x, y, z
	s.broadcast(M{"t": "pvp-respawn", "id": p.id, "x": x, "y": y, "z": z}, nil)
}

// ---------------------------------------------------------------- connections

func (s *server) writer(p *player) {
	ping := time.NewTicker(20 * time.Second)
	defer ping.Stop()
	for {
		select {
		case b := <-p.send:
			p.conn.SetWriteDeadline(time.Now().Add(10 * time.Second))
			if err := p.conn.WriteMessage(websocket.TextMessage, b); err != nil {
				p.conn.Close()
				return
			}
		case <-ping.C:
			p.conn.SetWriteDeadline(time.Now().Add(10 * time.Second))
			if err := p.conn.WriteMessage(websocket.PingMessage, nil); err != nil {
				p.conn.Close()
				return
			}
		case <-p.done:
			return
		}
	}
}

func (s *server) handleWS(w http.ResponseWriter, r *http.Request) {
	c, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	c.SetReadLimit(64 * 1024)
	p := &player{conn: c, send: make(chan []byte, 8192), done: make(chan struct{})}
	go s.writer(p)
	defer func() {
		s.drop(p)
		close(p.done)
		c.Close()
	}()

	c.SetReadDeadline(time.Now().Add(15 * time.Second)) // must say hello quickly
	c.SetPongHandler(func(string) error {
		c.SetReadDeadline(time.Now().Add(70 * time.Second))
		return nil
	})
	for {
		_, data, err := c.ReadMessage()
		if err != nil {
			return
		}
		c.SetReadDeadline(time.Now().Add(70 * time.Second))
		var m inMsg
		if json.Unmarshal(data, &m) != nil {
			continue
		}
		s.handle(p, &m)
	}
}

func setAPICORS(w http.ResponseWriter) {
	w.Header().Set("Access-Control-Allow-Origin", "*")
	w.Header().Set("Access-Control-Allow-Headers", "Content-Type, X-Server-Op-Code")
	w.Header().Set("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
	w.Header().Set("Cache-Control", "no-store")
}

func (s *server) authorizedOperator(code string) bool {
	return s.operatorCode != "" &&
		subtle.ConstantTimeCompare([]byte(code), []byte(s.operatorCode)) == 1
}

func (s *server) checkOperatorCode(r *http.Request, code string) (bool, bool) {
	host, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		host = r.RemoteAddr
	}
	now := time.Now()
	s.opMu.Lock()
	defer s.opMu.Unlock()
	if s.opAttempts == nil {
		s.opAttempts = map[string]operatorAttempt{}
	}
	attempt := s.opAttempts[host]
	if now.After(attempt.expires) {
		attempt = operatorAttempt{}
	}
	if attempt.failures >= 8 {
		return false, true
	}
	if s.authorizedOperator(code) {
		delete(s.opAttempts, host)
		return true, false
	}
	if attempt.failures == 0 {
		attempt.expires = now.Add(15 * time.Minute)
	}
	attempt.failures++
	s.opAttempts[host] = attempt
	return false, false
}

func writeAPIError(w http.ResponseWriter, status int, message string) {
	http.Error(w, message, status)
}

func (s *server) handleOperator(w http.ResponseWriter, r *http.Request) {
	setAPICORS(w)
	if r.Method == http.MethodOptions {
		w.WriteHeader(http.StatusNoContent)
		return
	}
	if r.Method != http.MethodPost {
		writeAPIError(w, http.StatusMethodNotAllowed, "Use POST to verify the operator code.")
		return
	}
	if s.operatorCode == "" {
		writeAPIError(w, http.StatusServiceUnavailable, "Server operator access is not configured.")
		return
	}
	r.Body = http.MaxBytesReader(w, r.Body, 4096)
	var request struct {
		Code string `json:"code"`
	}
	if err := json.NewDecoder(r.Body).Decode(&request); err != nil {
		writeAPIError(w, http.StatusBadRequest, "Invalid operator-code request.")
		return
	}
	authorized, blocked := s.checkOperatorCode(r, request.Code)
	if blocked {
		writeAPIError(w, http.StatusTooManyRequests, "Too many incorrect operator-code attempts. Try again later.")
		return
	}
	if !authorized {
		writeAPIError(w, http.StatusUnauthorized, "Incorrect server operator code.")
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func (s *server) handleDefinitions(w http.ResponseWriter, r *http.Request) {
	setAPICORS(w)
	if r.Method == http.MethodOptions {
		w.WriteHeader(http.StatusNoContent)
		return
	}
	switch r.Method {
	case http.MethodGet:
		entries, err := os.ReadDir(s.definitionsDir)
		if err != nil {
			writeAPIError(w, http.StatusInternalServerError, "Could not read shared server definitions.")
			log.Println("could not read shared definitions:", err)
			return
		}
		definitions := make([]json.RawMessage, 0, len(entries))
		for _, entry := range entries {
			if entry.IsDir() || !strings.EqualFold(filepath.Ext(entry.Name()), ".json") {
				continue
			}
			data, err := os.ReadFile(filepath.Join(s.definitionsDir, entry.Name()))
			if err != nil || !json.Valid(data) {
				writeAPIError(w, http.StatusInternalServerError, "A shared server definition file could not be read.")
				log.Printf("could not read shared definition %q: %v", entry.Name(), err)
				return
			}
			definitions = append(definitions, json.RawMessage(data))
		}
		w.Header().Set("Content-Type", "application/json; charset=utf-8")
		if err := json.NewEncoder(w).Encode(definitions); err != nil {
			log.Println("could not return shared definitions:", err)
		}
	case http.MethodPost:
		if s.operatorCode == "" {
			writeAPIError(w, http.StatusServiceUnavailable, "Server operator access is not configured.")
			return
		}
		authorized, blocked := s.checkOperatorCode(r, r.Header.Get("X-Server-Op-Code"))
		if blocked {
			writeAPIError(w, http.StatusTooManyRequests, "Too many incorrect operator-code attempts. Try again later.")
			return
		}
		if !authorized {
			writeAPIError(w, http.StatusUnauthorized, "Server operator access is required.")
			return
		}
		r.Body = http.MaxBytesReader(w, r.Body, 32<<20)
		data, err := io.ReadAll(r.Body)
		if err != nil {
			writeAPIError(w, http.StatusBadRequest, "Definition file is too large or could not be read.")
			return
		}
		var metadata struct {
			Schema   string `json:"schema"`
			Kind     string `json:"kind"`
			Name     string `json:"name"`
			Registry struct {
				ID int `json:"id"`
			} `json:"registry"`
		}
		if err := json.Unmarshal(data, &metadata); err != nil || !json.Valid(data) ||
			(metadata.Schema != "coop1.10.item-block-definition.v1" &&
				metadata.Schema != "coop1.10.item-block-definition.v2") ||
			(metadata.Kind != "tool" && metadata.Kind != "block") ||
			strings.TrimSpace(metadata.Name) == "" || metadata.Registry.ID > 65535 ||
			(metadata.Kind == "block" && metadata.Registry.ID > 255) ||
			(metadata.Kind == "tool" && metadata.Registry.ID < 119) ||
			(metadata.Kind == "block" && (metadata.Registry.ID < 30 ||
				metadata.Registry.ID == 99 || (metadata.Registry.ID >= 100 && metadata.Registry.ID <= 118))) {
			writeAPIError(w, http.StatusBadRequest, "Invalid item/block definition JSON.")
			return
		}
		path := filepath.Join(s.definitionsDir, fmt.Sprintf("%d.json", metadata.Registry.ID))
		s.mu.Lock()
		tmp, err := os.CreateTemp(s.definitionsDir, ".definition-*.tmp")
		if err != nil {
			s.mu.Unlock()
			writeAPIError(w, http.StatusInternalServerError, "Could not save the shared definition.")
			log.Println("could not save shared definition:", err)
			return
		}
		tmpPath := tmp.Name()
		defer os.Remove(tmpPath)
		if _, err = tmp.Write(data); err == nil {
			err = tmp.Close()
		} else {
			_ = tmp.Close()
		}
		if err == nil {
			err = os.Rename(tmpPath, path)
		}
		if err != nil {
			s.mu.Unlock()
			writeAPIError(w, http.StatusInternalServerError, "Could not save the shared definition.")
			log.Println("could not save shared definition:", err)
			return
		}
		s.broadcast(M{"t": "definition", "definition": json.RawMessage(data)}, nil)
		s.mu.Unlock()
		w.WriteHeader(http.StatusNoContent)
	default:
		writeAPIError(w, http.StatusMethodNotAllowed, "Use GET or POST for shared definitions.")
	}
}

// ---------------------------------------------------------------- time + persistence

func (s *server) loop() {
	tk := time.NewTicker(time.Second)
	n := 0
	for range tk.C {
		n++
		s.mu.Lock()
		if len(s.players) > 0 {
			s.wtime = math.Mod(s.wtime+1.0/dayLength, 1)
			if n%10 == 0 {
				s.broadcast(M{"t": "tm", "time": s.wtime}, nil)
			}
		}
		s.mu.Unlock()
		if n%30 == 0 {
			s.save(false)
		}
	}
}

func (s *server) save(force bool) {
	s.mu.Lock()
	if !force && !s.dirty {
		s.mu.Unlock()
		return
	}
	sf := saveFile{Seed: s.seed, Mode: s.mode, Time: s.wtime, PVP: s.pvp, Spawn: s.spawn, Edits: s.encodeEdits()}
	s.dirty = false
	path := s.savePath
	s.mu.Unlock()

	data, err := json.Marshal(sf)
	if err != nil {
		log.Println("save error:", err)
		return
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, data, 0o644); err != nil {
		log.Println("save error:", err)
		return
	}
	if err := os.Rename(tmp, path); err != nil {
		log.Println("save error:", err)
		return
	}
	log.Printf("world saved (%d edits)", len(sf.Edits)/5)
}

func (s *server) load() bool {
	data, err := os.ReadFile(s.savePath)
	if err != nil {
		return false
	}
	var sf saveFile
	if err := json.Unmarshal(data, &sf); err != nil {
		log.Println("could not read save file:", err)
		return false
	}
	s.seed, s.mode, s.wtime, s.pvp, s.spawn = sf.Seed, sf.Mode, sf.Time, sf.PVP, sf.Spawn
	for o := 0; o+5 <= len(sf.Edits); o += 5 {
		s.edits[binary.LittleEndian.Uint32(sf.Edits[o:o+4])] = sf.Edits[o+4]
	}
	return true
}

// ---------------------------------------------------------------- ngrok

var ngrokCmd *exec.Cmd

// startNgrok launches the ngrok CLI (must be installed, on PATH, and have an
// authtoken configured) and prints the public https URL it was given.
func startNgrok(port, domain string) {
	args := []string{"http", port, "--log=stderr", "--log-level=warn"}
	if domain != "" {
		args = append(args, "--domain="+domain)
	}
	cmd := exec.Command("ngrok", args...)
	cmd.Stderr = os.Stderr
	if err := cmd.Start(); err != nil {
		log.Println("could not start ngrok (installed and on PATH?):", err)
		return
	}
	ngrokCmd = cmd
	go func() {
		cmd.Wait()
		log.Println("ngrok exited")
	}()

	client := &http.Client{Timeout: 2 * time.Second}
	for i := 0; i < 40; i++ {
		time.Sleep(500 * time.Millisecond)
		resp, err := client.Get("http://127.0.0.1:4040/api/tunnels")
		if err != nil {
			continue
		}
		var out struct {
			Tunnels []struct {
				PublicURL string `json:"public_url"`
			} `json:"tunnels"`
		}
		err = json.NewDecoder(resp.Body).Decode(&out)
		resp.Body.Close()
		if err != nil {
			continue
		}
		for _, t := range out.Tunnels {
			if strings.HasPrefix(t.PublicURL, "https://") {
				log.Printf("  ONLINE:   %s   <- give this link to your friends", t.PublicURL)
				return
			}
		}
	}
	log.Println("ngrok started but no tunnel URL appeared; run `ngrok config check` and make sure your authtoken is set")
}

// ---------------------------------------------------------------- main

func main() {
	defaultAddr := ":8080"
	if port := os.Getenv("PORT"); port != "" {
		defaultAddr = ":" + port
	}
	addr := flag.String("addr", defaultAddr, "listen address")
	seedFlag := flag.Int64("seed", 0, "world seed, integer (0 = random); only used when creating a new world")
	mode := flag.String("mode", "survival", "survival or creative; only used when creating a new world")
	pvp := flag.Bool("pvp", false, "PvP on at start; only used when creating a new world")
	save := flag.String("save", "world.mcsrv.json", "world save file")
	operatorCode := flag.String("op-code", os.Getenv("EZZYCRAFT_OP_CODE"), "server operator code; required to unlock in-game server settings (or set EZZYCRAFT_OP_CODE)")
	definitionsDir := flag.String("definitions-dir", filepath.Join("server_data", "definitions"), "folder for shared item/block JSON definitions")
	useNgrok := flag.Bool("ngrok", false, "start an ngrok tunnel and print the public URL")
	ngrokDomain := flag.String("ngrok-domain", "", "optional reserved ngrok domain, e.g. my-name.ngrok-free.app")
	flag.Parse()

	s := &server{
		edits:          map[uint32]uint8{},
		players:        map[int]*player{},
		savePath:       *save,
		definitionsDir: *definitionsDir,
		operatorCode:   *operatorCode,
		wtime:          startTime,
	}
	if err := os.MkdirAll(s.definitionsDir, 0o755); err != nil {
		log.Fatal("could not create shared definitions folder: ", err)
	}
	if s.operatorCode == "" {
		log.Println("server operator settings are disabled (set -op-code to enable them)")
	}
	if s.load() {
		log.Printf("loaded world from %s (seed %d, %s, %d edits)", s.savePath, s.seed, s.mode, len(s.edits))
	} else {
		s.seed = int32(*seedFlag)
		if s.seed == 0 {
			s.seed = rand.Int31()
		}
		s.mode = "survival"
		if *mode == "creative" {
			s.mode = "creative"
		}
		s.pvp = *pvp
		s.dirty = true
		log.Printf("new world (seed %d, %s)", s.seed, s.mode)
	}

	go s.loop()

	sig := make(chan os.Signal, 1)
	signal.Notify(sig, os.Interrupt, syscall.SIGTERM)
	go func() {
		<-sig
		log.Println("shutting down, saving world...")
		s.save(true)
		if ngrokCmd != nil && ngrokCmd.Process != nil {
			ngrokCmd.Process.Kill()
		}
		os.Exit(0)
	}()

	http.HandleFunc("/ws", s.handleWS)
	http.HandleFunc("/api/operator", s.handleOperator)
	http.HandleFunc("/api/definitions", s.handleDefinitions)
	http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/" {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		w.Header().Set("Cache-Control", "no-cache")
		w.Write(indexHTML)
	})

	_, port, err := net.SplitHostPort(*addr)
	if err != nil {
		port = "8080"
	}
	log.Printf("listening on %s", *addr)
	log.Printf("  this PC:  http://localhost:%s", port)
	if addrs, err := net.InterfaceAddrs(); err == nil {
		for _, a := range addrs {
			if ipn, ok := a.(*net.IPNet); ok && !ipn.IP.IsLoopback() && ipn.IP.To4() != nil {
				log.Printf("  LAN:      http://%s:%s", ipn.IP, port)
			}
		}
	}
	if *useNgrok {
		go startNgrok(port, *ngrokDomain)
	}
	log.Fatal(http.ListenAndServe(*addr, nil))
}
